      "幂等是写接口的关键能力。创建订单、支付、扣库存这类接口应支持幂等键或业务唯一键，让超时重试、网关重放、客户端重复点击得到稳定结果。",
      "版本管理要优先保护已有调用方。新增可选字段、兼容扩展枚举、保留旧字段语义、设置废弃窗口和观测指标，可以让接口演进更平滑。",
