    id: "contract-test",
    zh: "契约测试",
    en: "Contract Test",
    area: "api",
    difficulty: "medium",
    engineeringValue: "用自动化测试固定消费者和提供者之间的接口承诺，提前发现兼容性破坏和联调风险。",
    explanation: [
      "契约测试验证服务之间约定的请求和响应是否仍然成立。它关注接口边界的可用性：消费者会发什么请求、期望什么状态码、字段、Header、错误体和行为，提供者发布前能否满足这些期望。",
      "消费者驱动契约测试由调用方定义真实使用场景。消费者测试会启动 Mock Provider，记录请求和期望响应生成契约文件；提供者测试拿契约文件验证真实服务或测试环境，确认实现满足消费者依赖。",
      "Pact 是典型工具链。消费者侧写出交互，例如 method、path、query、headers、body 和 expected response；Pact Broker 可以保存契约、记录验证结果，并用 can-i-deploy 判断服务组合是否具备发布条件。",
      "Spring Cloud Contract 更偏向 JVM 生态。团队可以用 Groovy、YAML 或 Java DSL 描述契约，再生成服务端测试、客户端 Stub 和消息契约测试，适合 Spring 微服务体系。",
      "契约测试和 OpenAPI 的关系是互补。OpenAPI 描述整个 API 的公共契约和文档，契约测试固定具体消费者实际依赖的交互；OpenAPI 适合全量规范校验，契约测试适合发布前验证真实调用方需求。",
      "契约测试覆盖的重点包括字段类型、必填字段、枚举、状态码、错误码、Header、认证要求、分页结构、时间格式和兼容扩展。对消息系统而言，还可以覆盖 topic、routing key、payload schema 和元数据。",
      "匹配规则比固定样例更重要。契约可以要求字段类型、格式、正则、最小数量和结构形状，避免把测试绑定到某个固定 ID、时间戳或随机值，同时保留接口语义约束。",
      "发布流程中，消费者先发布契约，提供者在 CI 中拉取契约并验证；提供者通过后再发布服务。多个消费者依赖同一提供者时，每个消费者的契约都要通过，才能证明发布对当前依赖方安全。",
      "契约测试擅长发现破坏性变更。字段删除、类型变化、必填字段新增、状态码变化、错误体结构变化、路径或 Header 改动都会在提供者验证阶段暴露。",
      "契约测试也有边界。它验证接口契约和关键交互，复杂业务流程、数据库事务、缓存一致性、鉴权策略和跨服务编排还需要单元测试、集成测试、端到端测试和线上监控补充。",
      "测试数据要保持可控。提供者验证通常需要 provider state，用来把服务准备到某个业务状态，例如用户存在、订单已支付、库存不足；状态准备要可重复、可清理、执行速度可接受。",
      "契约治理要处理版本和生命周期。废弃接口、字段迁移和新版本发布时，要更新契约、保留旧契约验证、观察消费者迁移进度，并在全部消费者升级后清理旧契约。",
      "参考来源：Pact 文档解释契约测试、消费者测试和发布判断；Martin Fowler 文章阐释消费者驱动契约思想；Spring Cloud Contract 文档提供 JVM 生态落地方式；OpenAPI Specification、Google AIP-180、Microsoft 与 Zalando API 指南补充契约、兼容性和 API 治理背景。",
    ],
