    id: "auth",
    zh: "认证授权",
    en: "Authentication and Authorization",
    area: "security",
    difficulty: "medium",
    engineeringValue: "确认调用者身份，并基于主体、资源、动作和上下文控制访问，保护业务数据与系统边界。",
    explanation: [
      "认证授权是后端安全的入口控制体系。认证负责确认调用者是谁，授权负责判断这个调用者能对哪个资源执行什么动作，两者共同决定一次请求是否可以进入业务逻辑。",
      "典型请求链路是：客户端提交凭证或令牌，认证层验证密码、MFA、Session、JWT、OAuth 2.0 Token 或 OpenID Connect ID Token，得到主体身份；授权层再根据角色、权限、策略、资源归属和环境上下文做访问决策。",
      "认证要关注凭证可信度。密码需要安全存储和限速保护，MFA 提高账号接管成本，Session 需要过期和撤销机制，JWT 需要校验签名、issuer、audience 和有效期，服务间调用要使用清晰的服务身份。",
      "授权要放在服务端可信边界执行。前端隐藏按钮只能改善体验，真实权限判断应在 API、服务层或策略引擎中完成，并覆盖读取、创建、修改、删除、导出、审批和管理动作。",
      "权限模型通常由主体、资源、动作和条件组成。主体可以是用户、服务账号或设备；资源可以带组织、租户、项目和所有者；动作要精确到业务语义；条件可以包含时间、来源 IP、设备状态和风险等级。",
      "常见授权模型包括 RBAC、ABAC 和策略引擎。RBAC 用角色聚合权限，适合岗位稳定的系统；ABAC 用主体、资源和环境属性表达细粒度规则；策略引擎把规则集中管理，便于审计和灰度。",
      "OAuth 2.0 主要解决授权委托。资源拥有者允许客户端访问特定范围的资源，授权服务器颁发访问令牌；OpenID Connect 在 OAuth 2.0 之上提供身份层，ID Token 用于表达用户身份认证结果。",
      "HTTP 状态码要表达认证授权结果。401 常用于认证缺失或失效，并可配 WWW-Authenticate；403 表示身份已识别但权限不足；安全敏感资源可以采用统一错误文案和审计记录来降低资源存在性暴露。",
      "多租户和组织层级是常见边界。每次授权都要带上租户、组织、资源归属和用户关系，避免只检查登录态或全局角色；跨租户管理、代理登录和数据导出尤其需要单独审计。",
      "缓存会影响权限实时性。用户角色、权限列表和策略结果可以缓存，但要设计失效机制、短 TTL、版本号或事件通知；权限收回、离职、密钥轮换和高风险操作需要更强实时性。",
      "审计是认证授权的安全闭环。登录、失败登录、权限变更、敏感资源访问、导出、审批、管理员操作和拒绝访问都应记录主体、资源、动作、结果、来源和 traceId。",
      "常见风险包括弱密码、暴力破解、会话固定、令牌泄露、越权访问、IDOR、水平越权、垂直越权、权限缓存过期和日志泄露敏感数据。防护重点是最小权限、默认拒绝、服务端校验、集中审计和自动化权限测试。",
      "参考来源：NIST Digital Identity Guidelines 和 Authentication 指南提供身份与认证保证框架；OWASP Authentication、Authorization 和 Access Control Cheat Sheet 提供 Web 安全实践；RFC 6749 解释 OAuth 2.0 授权框架；OpenID Connect Core 解释身份认证层；RFC 9110 支撑 HTTP 认证相关语义。",
    ],
