      "Session 认证把登录状态保存在服务端或集中存储中，客户端持有 Session ID Cookie。Cookie 应设置 HttpOnly、Secure、SameSite、合理过期时间和轮换策略，服务端要支持登出、撤销和异常会话清理。",
      "Token 认证常用于前后端分离和服务间调用。JWT 要校验签名、算法、issuer、audience、exp、nbf 和 jti；OAuth 2.0 Access Token 表达授权访问能力；OpenID Connect ID Token 表达用户身份认证结果。",
      "认证结果要和授权输入分开。认证得到的是主体身份和认证上下文，例如认证时间、认证强度、设备、来源和会话；授权再基于这些信息判断资源访问权限。",
