      "服务间认证需要明确服务身份。常见方式包括 mTLS、签名请求、短期服务令牌、云平台工作负载身份和 API Key；API Key 更适合识别调用方，敏感场景需要配合签名、轮换和权限范围。",
      "认证生命周期包括注册、登录、刷新、续期、登出、撤销、密码重置、设备管理和账号恢复。密码重置和账号恢复是高风险入口，需要一次性令牌、短有效期、审计和通知。",
      "认证日志要覆盖成功和失败。建议记录主体、认证方式、结果、失败原因类别、设备、IP、user agent、traceId 和风险标签；敏感凭证、验证码、完整令牌和密码哈希应留在日志之外。",
      "常见风险包括弱密码、撞库、暴力破解、会话劫持、令牌泄露、JWT 算法混淆、长期令牌、刷新令牌滥用、账号恢复绕过和敏感错误信息泄露。治理重点是强凭证、短期令牌、轮换、撤销、限速、MFA、审计和密钥管理。",
      "参考来源：NIST SP 800-63B 提供认证器和认证保证要求；OWASP Authentication、Password Storage 与 Session Management Cheat Sheet 提供 Web 认证实践；RFC 7519、RFC 6749 与 OpenID Connect Core 分别支撑 JWT、OAuth 2.0 和身份令牌；W3C WebAuthn 定义现代无密码认证能力；RFC 9110 支撑 HTTP 认证语义。",
