    engineeringValue: "在服务端维护登录态和用户上下文，让传统 Web 应用可以安全识别连续请求中的同一主体。",
    explanation: [
      "Session 是服务端保存的会话状态。用户登录成功后，服务端创建 sessionId，并把 sessionId 通过 Cookie 发给浏览器；后续请求自动携带 Cookie，服务端用 sessionId 找到用户身份、认证时间、权限摘要和会话状态。",
      "Session 的核心设计是把敏感状态留在服务端。浏览器只保存随机、高熵、不可预测的 sessionId；用户信息、权限、风险状态和撤销标记由服务端或集中式会话存储维护。",
      "Cookie 是 Session 最常见载体。Set-Cookie 可以设置 HttpOnly、Secure、SameSite、Domain、Path、Expires 和 Max-Age；HttpOnly 降低脚本读取风险，Secure 要求 HTTPS，SameSite 能减少跨站请求自动带 Cookie 的风险。",
      "Session 生命周期包括创建、续期、轮换、过期、登出和撤销。登录成功后建议轮换 sessionId，权限提升或敏感操作后可再次轮换；登出、密码修改、MFA 重置、设备移除和风控命中时应撤销相关会话。",
      "会话存储可以在内存、数据库、Redis 或专用 Session Store 中实现。单机内存简单但扩展性弱，集中式存储适合多实例部署；高并发场景要关注 TTL、淘汰策略、热点 Key、连接池和故障降级。",
      "Session 过期策略要兼顾安全和体验。常见做法是设置绝对过期时间、空闲过期时间和滑动续期；高风险账号、管理员、共享设备和支付类操作适合更短有效期或重新认证。",
      "Session 与 JWT 的关键区别在状态位置。Session 状态在服务端，撤销和权限实时更新更直接；JWT 常把声明放在令牌中，跨服务验证方便，但撤销、权限变更和令牌泄露治理需要额外机制。",
      "Session 容易与 CSRF 相关。浏览器会自动携带同站点范围内的 Cookie，状态变更接口需要结合 SameSite、CSRF Token、Origin/Referer 校验和安全的 CORS 配置。",
      "Session 固定攻击发生在攻击者让用户使用已知 sessionId 登录。防护重点是登录成功后重新生成 sessionId，拒绝 URL 中传递 sessionId，并在敏感状态变化时轮换会话。",
      "会话劫持通常来自 XSS、网络窃听、日志泄露、Cookie 配置错误或设备失控。治理重点是 HTTPS、HttpOnly、Secure、CSP、日志过滤、短 TTL、设备管理、异常登录检测和会话撤销。",
      "分布式系统要处理会话一致性。权限变更、账号冻结、租户切换和管理员降权需要及时影响已登录会话；可以使用版本号、事件通知、短 TTL 或每次关键请求查询最新状态。",
      "Session 审计应记录创建、续期、轮换、登出、撤销、过期和异常访问，字段包括用户、设备、IP、user agent、结果、原因和 traceId；完整 sessionId 应进行哈希或截断后再进入日志。",
      "参考来源：OWASP Session Management Cheat Sheet 提供 Session ID、Cookie 标志、生命周期和防护实践；RFC 6265、MDN Set-Cookie 与 HTTP Cookies 说明 Cookie 机制；OWASP CSRF Cheat Sheet 补充 SameSite 与 CSRF Token；NIST 认证指南与 RFC 9110 支撑会话认证和 HTTP 语义。",
    ],
