    id: "jwt",
    zh: "JWT",
    en: "JSON Web Token",
    area: "security",
    difficulty: "medium",
    engineeringValue: "用可签名的自包含令牌在多服务之间传递身份、授权声明和会话上下文，降低集中式会话查询成本。",
    explanation: [
      "JWT 是一种紧凑的声明承载格式。它把 header、payload 和 signature 用点号拼接成字符串，常用于访问令牌、身份令牌和服务间认证上下文。",
      "header 描述令牌类型和算法，例如 typ、alg、kid；payload 放声明 claims，例如 sub、iss、aud、exp、nbf、iat、jti、scope；signature 用密钥对 header 和 payload 签名，接收方通过验签确认内容完整且来自可信签发方。",
      "JWT 本身是编码后的 JSON 声明集合。签名可以防篡改，内容默认可被持有者解码查看；敏感数据、密码、手机号、权限全集和内部风控信息应放在服务端或使用加密令牌方案。",
      "验证 JWT 要做完整校验。服务端应固定允许算法，验证签名、issuer、audience、expiration、not before、issued at、token id、scope 和业务上下文，并拒绝算法混淆、错误 key、过期和受众不匹配的令牌。",
      "密钥管理是 JWT 安全核心。对称算法用共享密钥，非对称算法用私钥签名和公钥验签；kid 可以帮助选择密钥，JWK/JWKS 用于发布公钥集合，密钥轮换要支持新旧密钥并行一段时间。",
      "访问令牌要短期有效。短 exp 可以降低泄露后的影响范围；长期登录体验通常由 Refresh Token 或 Session 管理，刷新令牌需要服务端存储、撤销、轮换和审计。",
      "JWT 的优势是跨服务验证方便。资源服务可以在本地验签并读取声明，减少集中 Session 查询；它适合微服务、API 网关、移动端和第三方开放接口中的短期访问令牌。",
      "JWT 的代价是撤销和权限实时更新更复杂。令牌签发后声明会在有效期内保持不变，权限收回、账号冻结、租户变更和角色调整需要短有效期、黑名单、令牌版本号或 introspection 机制配合。",
      "JWT 大小会影响性能。声明越多，Authorization Header 越大，网关、代理、浏览器和日志系统都会承担额外开销；令牌中只放调用方判断所需的最小声明。",
      "在浏览器中存储 JWT 要谨慎。localStorage 暴露于 XSS 风险，Cookie 需要关注 CSRF；常见策略是短期 Access Token 放内存，Refresh Token 放 HttpOnly、Secure、SameSite Cookie，并配合 CSRF 防护。",
      "OpenID Connect 中的 ID Token 是 JWT 的常见用法。ID Token 表达用户认证结果，Access Token 表达访问资源的授权能力，两者用途、受众和校验要求应分开处理。",
      "常见风险包括接受 none 算法、算法混淆、跳过 aud/iss 校验、令牌过期时间过长、在令牌中放敏感数据、kid 注入、密钥泄露、日志记录完整令牌和刷新令牌缺少轮换。",
      "参考来源：RFC 7519 定义 JWT；RFC 8725 提供 JWT 安全最佳实践；RFC 7515 和 RFC 7517 支撑 JWS 签名与 JWK 密钥发布；OpenID Connect Core 与 RFC 6749 说明 ID Token 和访问令牌场景；OWASP JWT Cheat Sheet 与 NIST 认证指南补充安全落地建议。",
    ],
