    explanation: [
      "OAuth 2.0 是授权框架。它让资源拥有者授权客户端访问资源服务器上的受保护资源，授权服务器负责发放令牌，资源服务器根据令牌和 scope 决定访问范围。",
      "OAuth 2.0 的核心角色包括 resource owner、client、authorization server 和 resource server。用户通常是资源拥有者，第三方应用是客户端，账号中心或身份平台是授权服务器，业务 API 是资源服务器。",
      "Authorization Code + PKCE 是现代通用主流程。客户端把用户带到授权服务器登录和同意授权，授权服务器返回 authorization code；客户端用 code_verifier 换取 token，PKCE 能降低授权码被拦截后的滥用风险。",
      "Client Credentials 适合服务间调用。客户端用自身凭据向授权服务器换取 Access Token，代表服务身份访问资源；它适合后台任务、机器对机器调用和平台内部服务集成。",
      "Device Authorization Grant 适合输入受限设备。电视、CLI 或 IoT 设备显示 user code 和验证地址，用户在另一台设备上完成授权，设备轮询 token endpoint 获取令牌。",
      "Access Token 表达访问能力。资源服务器校验令牌、scope、audience、issuer 和有效期；令牌可以是 JWT，也可以是不透明字符串并通过 introspection 查询状态。",
      "Refresh Token 用于延续授权会话。它应被严格保护，结合轮换、撤销、设备绑定和审计；浏览器和移动端场景要关注存储位置、XSS、CSRF、设备丢失和并发刷新。",
      "scope 是最小授权范围的表达。scope 应具体、稳定、可审计，例如 orders:read、payments:write；授权页面和 API 文档要让用户和开发者理解每个 scope 的实际影响。",
      "state 和 redirect_uri 是防攻击关键点。state 用于绑定请求和回调，降低 CSRF 风险；redirect_uri 必须精确注册和校验，避免授权码被发到攻击者控制的地址。",
      "OAuth 2.0 常和 OpenID Connect 搭配。OAuth 2.0 负责授权访问资源，OpenID Connect 在其上提供身份认证层，ID Token 表达用户身份，Access Token 表达资源访问权限。",
      "安全实践要关注公共客户端。移动端、浏览器和单页应用难以安全保存 client secret，应使用 Authorization Code + PKCE，避免隐式流程，把短期 Access Token、刷新令牌轮换和安全存储配合起来。",
      "令牌治理包括撤销、查询和轮换。Token Revocation 支持主动撤销 Refresh Token 或 Access Token，Token Introspection 支持资源服务器查询不透明令牌状态，密钥轮换支持 JWT 签名安全演进。",
      "常见风险包括 redirect_uri 校验宽松、缺少 state、使用隐式流程、scope 过大、Refresh Token 长期有效、客户端密钥泄露、混淆 ID Token 和 Access Token，以及资源服务器只解码令牌但跳过校验。",
      "参考来源：RFC 6749 定义 OAuth 2.0 框架；RFC 9700 提供安全最佳实践；RFC 7636、RFC 8252 和 RFC 8628 分别支撑 PKCE、原生应用和设备授权；RFC 7009 与 RFC 7662 支撑撤销和 introspection；OpenID Connect Core 解释身份层；OWASP 认证资料补充落地安全建议。",
    ],
