    id: "openid-connect",
    zh: "OpenID Connect",
    en: "OpenID Connect",
    area: "security",
    difficulty: "hard",
    engineeringValue: "在 OAuth 2.0 之上标准化用户身份认证，支撑登录、单点登录、身份联邦和跨系统账号绑定。",
    explanation: [
      "OpenID Connect 是 OAuth 2.0 之上的身份认证层。OAuth 2.0 提供授权框架，OIDC 增加 openid scope、ID Token、UserInfo Endpoint、Discovery 和标准 claims，让客户端能验证用户身份并获取基础资料。",
      "OIDC 的核心角色包括 End-User、OpenID Provider 和 Relying Party。OpenID Provider 负责认证用户并签发令牌，Relying Party 是接入登录能力的业务系统，End-User 是正在登录的人。",
      "主流登录流程是 Authorization Code + PKCE。客户端生成 state、nonce 和 code_verifier，把用户带到授权端点；用户完成认证后返回 code；客户端用 code 和 code_verifier 调 token endpoint，获得 ID Token、Access Token，按需获得 Refresh Token。",
      "ID Token 是表达认证结果的 JWT。关键 claims 包括 iss、sub、aud、exp、iat、nonce、auth_time、acr、amr、azp；其中 iss 表示签发者，sub 表示该签发者下稳定用户标识，aud 表示接收方客户端，exp 和 iat 约束有效时间。",
      "ID Token 校验是落地重点。客户端要从 discovery 文档确认 issuer、authorization_endpoint、token_endpoint、jwks_uri 和支持算法，拉取 JWKS 后按 kid 选择公钥，验证签名、alg、iss、aud、azp、exp、iat、nonce 和重放风险。",
      "UserInfo Endpoint 用 Access Token 返回用户资料 claims。调用后要校验 UserInfo 里的 sub 与 ID Token 的 sub 完全一致；profile、email、phone 等资料可能受 scope、隐私策略和供应商配置影响。",
      "本地账号绑定优先使用 issuer + sub 作为稳定键。email 适合做联系属性和展示属性，email_verified 只能说明提供方在某个时间点确认过邮箱，跨租户、跨身份源和邮箱变更都要保留审计与重新绑定流程。",
      "state 和 nonce 解决不同风险。state 绑定授权请求与回调，降低 CSRF 和跳转混淆风险；nonce 绑定客户端会话与 ID Token，降低 ID Token 重放和替换风险。",
      "ID Token 与 Access Token 的职责要分开。ID Token 给 Relying Party 验证登录身份；Access Token 给资源服务器判断 API 访问能力。API 鉴权使用 Access Token、scope、audience 和资源侧策略。",
      "Discovery 让客户端通过 /.well-known/openid-configuration 获取配置。多租户身份平台要按租户 issuer 隔离配置、JWKS 缓存、回调地址和账号绑定，避免把一个租户的 token 放进另一个租户的信任域。",
      "密钥轮换要按 JWKS 设计缓存策略。服务端会新增 key、切换签名 key、移除旧 key；客户端应根据 kid 缓存公钥并支持刷新，遇到未知 kid 可以重新拉取 JWKS，再按固定算法白名单验证。",
      "常见边界包括时钟偏移、nonce 存储过期、用户取消授权、scope 缺失、claims 缺失、JWKS 拉取失败、算法配置变化、回调地址不匹配、同邮箱多账号、组织租户切换和前后端会话状态不同步。",
      "常见风险包括只解码 ID Token、跳过签名校验、把 ID Token 当 API 访问凭证、用 email 当唯一主键、信任未校验的 UserInfo、放宽 redirect_uri、忽略 nonce、未处理 JWKS 轮换和混用多个 issuer。",
      "参考来源：OpenID Connect Core 定义身份层、ID Token、UserInfo 和校验规则；OpenID Connect Discovery 与 RFC 8414 定义元数据发现和 jwks_uri；RFC 6749 与 RFC 7636 支撑授权码和 PKCE；RFC 7519、RFC 8725 和 RFC 7517 支撑 JWT、JWT 安全实践和 JWK 密钥发布。",
    ],
