    id: "abac",
    zh: "ABAC",
    en: "Attribute-Based Access Control",
    area: "security",
    difficulty: "hard",
    engineeringValue: "用主体、资源、动作和环境属性表达动态授权规则，支撑多租户、数据分级、上下文风控和细粒度访问控制。",
    explanation: [
      "ABAC 是基于属性的访问控制。系统把一次访问请求拆成主体、资源、动作和环境，再用策略规则评估这些属性是否满足访问条件。",
      "主体属性描述谁在请求，例如 userId、tenantId、department、role、clearance、MFA 状态和风险等级。资源属性描述被访问对象，例如 ownerId、tenantId、classification、region、projectId、status 和标签。",
      "动作属性描述要做什么，例如 read、write、approve、export、delete。环境属性描述请求上下文，例如时间、IP、设备、网络区域、地理位置、请求来源、认证强度和会话新鲜度。",
      "ABAC 的优势是表达能力强。它可以写出“同租户成员可读本项目普通数据”“财务审批人在工作时间且完成 MFA 后可审批付款”“受限数据只能在公司网络导出”这类动态条件。",
      "策略评估一般由 PEP、PDP、PIP 和 PAP 协作。PEP 在 API、网关或服务内拦截请求；PDP 计算允许或拒绝；PIP 提供用户、资源和环境属性；PAP 管理策略发布、版本和审批。",
      "属性质量决定 ABAC 质量。属性要有权威来源、更新机制、类型约束、命名规范和可信边界；过期部门、错误标签、跨系统枚举不一致都会导致授权结果偏差。",
      "策略语言要支持可测试和可解释。生产策略应有版本、审批、灰度、单元测试、回归样例、决策日志和命中原因，方便定位一次 allow 或 deny 来自哪些规则和属性。",
      "ABAC 常与 RBAC 组合使用。RBAC 提供稳定职责集合，ABAC 在此基础上叠加租户、资源归属、数据分级、时间窗口、MFA、设备和风险信号，兼顾可维护性与细粒度。",
      "AWS IAM 是 ABAC 工程实践样例。它可以使用 principal tag、resource tag、request tag 和 condition key 编写策略；策略评估中显式拒绝优先，多个策略类型共同影响最终结果。",
      "默认拒绝适合 ABAC 策略基线。新增资源类型、动作、标签和属性来源时，应让未匹配策略的请求落到拒绝结果，并用策略测试覆盖 allow、deny、缺失属性和冲突规则。",
      "缓存策略要谨慎。主体属性和资源属性可能频繁变化，缓存授权结果会带来撤权延迟；常见做法是缓存短生命周期属性、记录版本号，并在高风险权限上实时查询或主动失效。",
      "多租户场景要把 tenantId 放进主体、资源和策略。每条数据、每个资源、每个授权请求都要携带租户边界，后台任务、批处理、导出和管理员操作也要经过同样的边界校验。",
      "常见边界包括属性缺失、属性过期、标签被错误修改、策略冲突、时间窗口跨时区、组织关系变更、权限缓存失效、跨服务属性语义不同、批量操作部分命中和审计日志过大。",
      "常见风险包括策略分散在代码里、属性来源不可信、标签治理缺失、策略无测试、缺少决策日志、把前端传入属性直接用于授权、显式拒绝规则缺失和数据查询层绕过授权。",
      "参考来源：NIST SP 800-162 定义 ABAC 及主体、对象、操作、环境属性评估模型；NIST NCCoE 补充企业落地考虑；OWASP 授权与访问控制资料强调服务端校验、最小权限和默认拒绝；AWS IAM 文档展示标签驱动 ABAC 与策略评估；OPA 文档提供策略引擎化落地方式；NIST RBAC 项目帮助对比角色模型。",
    ],
