    id: "permission-model",
    zh: "权限模型",
    en: "Permission Model",
    area: "security",
    difficulty: "hard",
    engineeringValue: "把主体、资源、关系、动作、条件和租户边界抽象成稳定规则，让授权系统可设计、可测试、可审计、可演进。",
    explanation: [
      "权限模型是授权系统的领域模型。它描述谁可以在什么范围内对什么资源执行什么动作，以及这个判断依赖哪些角色、关系、属性、策略和上下文。",
      "基本元素包括主体、资源、动作、关系、条件和作用域。主体可以是用户、服务账号、设备或代理；资源可以是组织、项目、文档、订单或字段；动作可以是 read、write、approve、export、delete。",
      "建模顺序通常从资源开始。先列出业务资源和层级关系，再列动作集合和敏感动作，然后补充主体类型、组织租户、所有权、成员关系、数据分级和审批规则。",
      "RBAC 适合表达岗位职责。角色承载一组权限，用户绑定角色；它让后台、企业系统和运维平台的权限管理更容易审计，关键点是角色数量、角色继承和职责分离。",
      "ABAC 适合表达动态条件。主体属性、资源属性、动作和环境共同进入策略，例如同租户、资源标签、数据密级、工作时间、MFA 状态和风险等级。",
      "ReBAC 适合表达关系图。用户与组织、团队、项目、文件夹、文档之间的 owner、member、viewer、editor 等关系可以层层传递，适合协作文档、网盘、代码仓库和多级组织权限。",
      "Zanzibar 类模型把授权拆成关系元组和模型定义。关系元组记录 user、relation、object，模型定义描述关系如何推导权限；OpenFGA 使用类似概念，把类型、关系、对象和元组组合成可查询的授权图。",
      "权限模型要明确决策语义。多个来源同时命中时，要定义允许、拒绝、显式拒绝、继承、覆盖、冲突合并和默认拒绝规则；AWS IAM 的策略评估展示了显式拒绝优先这类工程语义。",
      "多租户边界应进入模型核心。主体、资源、关系元组、策略和审计日志都要带租户或组织边界，超级管理员、跨租户运营账号和后台任务要有独立规则和可追踪审批。",
      "授权检查要靠服务端执行。菜单、按钮和前端路由只负责展示体验，API、任务、批处理、导出、搜索、详情页和管理端入口都要经过统一授权检查。",
      "模型演进要可迁移。新增动作、拆分资源、角色重命名、组织层级变化和租户合并都可能改变授权结果；模型需要版本、兼容策略、灰度、回滚和批量校验工具。",
      "测试是权限模型的核心交付物。每个模型变更都应配套正例、反例、边界例和回归例，覆盖允许、拒绝、缺失关系、继承链、跨租户、管理员、临时授权和撤权延迟。",
      "审计日志要记录决策上下文。关键字段包括主体、资源、动作、租户、命中的角色或策略、关系路径、属性快照、请求 ID、决策结果和模型版本，方便复盘越权与误拒。",
      "常见边界包括角色爆炸、资源层级循环、继承链过深、关系元组过期、批量查询性能、搜索列表权限过滤、字段级权限、缓存撤权延迟和跨系统权限语义不一致。",
      "常见风险包括用用户 ID 写死例外、把权限判断散落在业务代码里、只做入口校验、列表接口漏过滤、后台任务绕过模型、管理员权限无审批、模型无测试和审计日志缺少决策依据。",
      "参考来源：OWASP 授权与访问控制资料强调服务端授权、最小权限和默认拒绝；NIST RBAC 与 ABAC 资料提供角色和属性模型基础；AWS IAM 展示策略评估语义；OPA 提供策略引擎思路；Google Zanzibar 与 OpenFGA 文档说明关系图、关系元组、模型定义和模型测试。",
    ],
