    id: "policy-engine",
    zh: "策略引擎",
    en: "Policy Engine",
    area: "security",
    difficulty: "hard",
    engineeringValue: "把授权、准入、配置合规和风控规则从业务代码中抽离为可版本化、可测试、可审计的策略决策能力。",
    explanation: [
      "策略引擎是专门执行策略决策的组件。业务系统把请求上下文、主体、资源、动作和环境数据交给策略引擎，策略引擎返回 allow、deny、原因、命中策略和附加约束。",
      "策略引擎的价值是把决策逻辑集中管理。授权规则、Kubernetes 准入规则、基础设施合规、数据访问、风控阈值和发布门禁都可以用策略语言表达，并通过统一流程发布和审计。",
      "典型架构包含 PEP 与 PDP。PEP 位于 API 网关、服务中间件、Envoy、Kubernetes Admission Controller 或数据访问层，负责拦截和执行；PDP 是策略引擎，负责根据输入和策略计算决策。",
      "OPA 是通用策略引擎。它用 Rego 语言查询结构化数据，适合 API 授权、Kubernetes 准入控制、CI/CD 合规和配置校验；业务服务可以通过本地库、sidecar 或远程服务调用 OPA。",
      "策略数据要和策略代码一起治理。Rego 策略通常依赖用户、租户、资源、标签、组织树和风险信号；这些数据可以通过 bundle、数据 API 或外部查询同步，核心挑战是新鲜度、体积和可信来源。",
      "Bundle 是 OPA 常见发布方式。策略文件和数据打包成 bundle 后由 OPA 拉取，方便版本化、灰度和回滚；生产环境要监控 bundle 下载失败、版本滞后和策略加载错误。",
      "Cedar 是面向授权的策略语言。它围绕 principal、action、resource、context 表达权限，支持 RBAC 和 ABAC 组合；Amazon Verified Permissions 使用 Cedar 管理应用内细粒度权限。",
      "策略决策要有稳定语义。常见语义包括默认拒绝、显式拒绝优先、多个 permit 合并、条件约束、决策原因和确定策略；这些语义要写进平台规范和测试用例。",
      "策略引擎与权限模型关系紧密。权限模型定义资源、动作、主体、关系和属性；策略引擎把模型翻译成可执行规则，并提供批量校验、解释、测试和审计能力。",
      "策略发布要像代码发布一样管理。策略应经过代码评审、静态检查、单元测试、回归测试、影子评估、灰度、审批、版本标记和快速回滚，避免一次策略变更造成大面积误拒或越权。",
      "决策日志是排障关键。日志要记录输入摘要、主体、资源、动作、租户、策略版本、命中规则、决策结果、耗时、请求 ID 和异常信息，同时避免输出敏感属性和完整令牌。",
      "性能设计要贴近调用路径。同步授权检查对延迟敏感，常用本地 sidecar、内嵌库、批量决策、短缓存和预编译策略；集中远程 PDP 便于统一治理，但要处理网络延迟、可用性和降级策略。",
      "常见边界包括策略冲突、数据源延迟、策略版本漂移、远程 PDP 不可用、批量授权超时、缓存撤权延迟、策略语言学习成本、调试困难和跨团队策略所有权不清。",
      "常见风险包括把用户输入直接当可信属性、策略无测试、默认允许、日志泄露敏感数据、决策结果缓存过久、业务绕过 PEP、策略发布缺少回滚和策略与数据版本不一致。",
      "参考来源：OPA 文档说明通用策略引擎、Rego、API 与 bundle 管理；Cedar 和 Amazon Verified Permissions 文档说明 principal、action、resource、context 与授权决策语义；AWS IAM 策略评估展示显式拒绝与策略合并；OWASP 授权资料强调服务端授权、最小权限和审计；OpenFGA 概念帮助理解关系型授权场景。",
    ],
