    id: "rate-limit",
    zh: "限流",
    en: "Rate Limiting",
    area: "traffic",
    difficulty: "medium",
    engineeringValue: "限制请求速率和并发占用，保护服务、下游依赖、预算和公平性。",
    explanation: [
      "限流（Rate Limiting）是在入口、网关、服务或下游调用处为请求设置速率、并发、配额或成本上限。它的目标是让系统在突发流量、恶意请求、客户端重试、单租户过量使用和下游容量不足时保持可用，并把资源按用户、租户、接口或业务优先级分配得更公平。",
      "限流先要定义维度和窗口：常见维度有用户、API Key、租户、IP、设备、接口、方法、地域、业务动作和请求成本；常见窗口有每秒、每分钟、每小时、每天以及滚动窗口。GitHub 这类公开 API 会区分认证方式、资源类型和主/次级限流，说明真实系统通常会有多层规则同时生效。",
      "算法上，固定窗口实现简单但边界容易出现突刺；滑动窗口更平滑，代价是存储和清理成本更高；令牌桶控制长期平均速率并允许有限突发；漏桶把请求平滑输出，适合保护下游稳定处理速率；并发限流控制正在执行的请求数量，适合慢接口、长轮询、文件上传和外部依赖调用。",
      "响应语义要对客户端友好。超过限制时通常返回 429 Too Many Requests，并通过 Retry-After 或 RateLimit 字段告诉客户端等待时间、剩余额度和限流策略。对调用方来说，正确行为是降低速率、使用指数退避和抖动、缓存可复用结果，并把限流当成正常的容量信号处理。",
      "分布式限流需要在精度、延迟和可用性之间取舍。网关本地限流延迟低、依赖少，适合吸收突发；全局限流依赖 Redis、专用限流服务或 Envoy gRPC Rate Limit Service，适合多实例共享配额；混合方案常用本地令牌桶吸收峰值，再用全局服务维护租户级或账号级预算。",
      "工程风险集中在误伤和绕过。按 IP 限流会受到 NAT、代理和移动网络影响；按用户限流需要登录态稳定；按 Header 限流需要防伪造；按接口限流要考虑高成本接口和低成本接口的差异；限流点过晚会让数据库、缓存或消息队列先被打满。高价值链路应保留独立配额，后台任务、爬虫、导出和批处理要单独治理。",
      "上线限流建议先 dry run 观测命中率，再逐步开启拦截；指标至少包含通过数、拒绝数、延迟、队列长度、配额剩余、规则维度、上游错误率和租户分布。响应体要包含稳定错误码和可读提示，方便客户端、SRE 和业务方判断是达到配额、触发风控、并发过高还是下游保护。",
      "参考来源：RFC 6585 定义 429 Too Many Requests 与 Retry-After；IETF RateLimit 字段草案描述服务端暴露配额策略和剩余额度；AWS API Gateway、Envoy、NGINX 文档说明云网关、全局限流、本地限流和漏桶配置；GitHub、Stripe、Cloudflare 文档展示公开 API、并发限制、复杂度计分和 WAF 限流规则的工程实践。",
    ],
