    id: "leaky-bucket",
    zh: "漏桶",
    en: "Leaky Bucket",
    area: "traffic",
    difficulty: "medium",
    engineeringValue: "把突发请求排队并按稳定速率释放，保护下游服务的处理节奏。",
    explanation: [
      "漏桶（Leaky Bucket）是一种流量整形和限流算法：请求先进入容量有限的桶，桶以固定速率向外“漏水”，也就是按稳定节奏放行请求；桶满后，新请求会被拒绝、丢弃或返回限流响应。它的核心目标是削平突发，把入口尖峰转换成下游可承受的稳定输出。",
      "用一个例子理解：漏出速率 100 req/s、桶容量 300。瞬间来了 250 个请求时，它们进入队列并在约 2.5 秒内匀速处理；瞬间来了 600 个请求时，前 300 个进入桶，后续请求触发拒绝或降级。这里的速率决定下游节奏，容量决定能吸收多少排队压力。",
      "漏桶适合严格控制出口速率，例如短信发送、支付回调、第三方 API 调用、任务派发、写库削峰和网关排队。NGINX 的 limit_req 使用共享内存记录状态，并通过 rate、burst、delay/nodelay 等参数控制请求速率、突发队列和延迟策略；Sentinel 的匀速排队模式也用固定间隔让请求通过。",
      "令牌桶和漏桶的关键差异在突发处理。令牌桶通过积累令牌允许短时间快速放行，适合保留合理突发；漏桶把突发请求排队后按固定速率释放，适合保护下游处理节奏。入口限流常用令牌桶，出口整形、任务消费和调用第三方服务常用漏桶。",
      "参数设计看三个量：leak rate、bucket capacity、max wait time。leak rate 应贴近下游稳定吞吐；bucket capacity 应等于系统愿意承受的排队深度；max wait time 用来限制用户等待和内存占用。队列型漏桶要同时考虑请求超时、客户端断开、重试风暴和队列公平性。",
      "边界情况集中在排队成本。桶容量过大会把失败延后，导致响应时间飙升、内存占用上升和过期请求继续执行；容量过小会削掉可接受突发；固定出口速率遇到慢下游时仍可能堆积；多实例本地漏桶会让总出口速率随实例数增长；分布式漏桶需要共享时钟、原子计数和故障降级策略。",
      "排查漏桶问题时看入桶速率、出桶速率、队列长度、等待时间、拒绝数、超时数、下游错误率和 429 响应比例。上线建议先用压测覆盖瞬时突发、持续超速、下游变慢、客户端超时、实例扩缩容和限流配置热更新，并为队列等待设置明确上限。",
      "参考来源：NGINX 官方文档和博客说明 rate、burst、delay/nodelay 与 limit_req 的工程语义；Sentinel 文档说明匀速排队模式；Wikipedia 梳理漏桶作为队列和计量器的两种表述；RFC 6585 提供 429 状态码语义。",
    ],
