    id: "circuit-breaker",
    zh: "熔断",
    en: "Circuit Breaker",
    area: "resilience",
    difficulty: "medium",
    engineeringValue: "在依赖持续失败或变慢时快速失败，保护线程池、连接池和调用链资源。",
    explanation: [
      "熔断（Circuit Breaker）是一种故障隔离模式：调用下游时持续统计失败、超时或慢调用比例，达到阈值后短时间停止真实调用，直接返回错误或降级结果。它的目标是让系统快速释放资源，给故障依赖恢复时间，减少级联故障。",
      "熔断器通常有三种状态：Closed 正常放行并统计结果；Open 直接拒绝或走降级；Half-Open 在等待一段恢复时间后放少量探测请求。如果探测成功率达标，状态回到 Closed；如果探测继续失败，状态回到 Open 并延长保护。",
      "触发条件要用滑动窗口和最小请求量配合。只看单次失败会过度敏感；只看错误率会漏掉慢调用耗尽线程的问题。Resilience4j 和 Sentinel 都支持按失败率、慢调用比例、最小调用数、窗口大小和半开探测数来配置熔断。",
      "熔断常和超时、重试、降级、舱壁隔离一起出现。超时定义一次调用最多占用多久；重试处理瞬时故障；熔断识别持续故障并快速失败；降级给用户可接受结果；舱壁隔离把不同依赖的资源池分开，避免一个下游拖垮整个服务。",
      "参数设计看五个量：统计窗口、最小请求数、失败率阈值、慢调用阈值、Open 等待时长。窗口太短会抖动，窗口太长会反应迟缓；最小请求数太低会误判；Open 等待太短会频繁探测故障依赖，太长会延迟恢复。",
      "边界情况集中在状态抖动和误判。低流量接口样本少，熔断阈值要更保守；半开探测并发要限制，避免恢复瞬间再次压垮下游；客户端重试会放大熔断前的流量；多实例各自熔断会出现状态不一致；错误分类要区分业务失败、鉴权失败、参数错误和基础设施故障。",
      "排查熔断问题时看熔断状态、失败率、慢调用比例、窗口调用数、半开探测结果、被拒绝请求数、下游延迟、连接池等待和线程池占用。上线建议先观察模式或低阈值告警，再灰度启用，并为每个熔断规则配置清晰的降级响应和告警。",
      "参考来源：Martin Fowler 解释熔断器状态模型；Microsoft Azure Architecture Center 说明云服务中的熔断模式和恢复策略；Resilience4j、Sentinel、Polly 文档提供失败率、慢调用、半开探测和窗口参数；OpenTelemetry 资料支撑指标与链路观测。",
    ],
    typicalProblems: [
      "熔断解决什么级联故障问题",
      "Closed、Open、Half-Open 三种状态如何流转",
      "失败率、慢调用比例、最小请求数和统计窗口怎样配置",
      "熔断和超时、重试、降级、舱壁隔离分别承担什么职责",
      "半开探测为什么要限制并发和请求数",
      "低流量接口怎样避免熔断误判",
      "哪些异常应该计入熔断失败率",
      "客户端重试为什么会放大熔断前的压力",
      "多实例熔断状态不一致会带来什么影响",
      "如何监控和排查熔断器频繁开关",
    ],
    practiceAdvice: [
      "按依赖和接口维度设置独立熔断规则，用失败率、慢调用比例、最小请求数和滑动窗口共同判断健康状态",
      "为 Open 状态配置明确降级结果，为 Half-Open 状态限制探测并发，并把业务错误和基础设施错误分开统计",
      "上线前用故障注入验证超时、慢调用、连续失败、半开恢复和降级路径，监控状态变化、拒绝数、慢调用比例和下游资源占用",
    ],
    prerequisites: ["api-gateway", "timeout"],
