      "边界情况包括 DNS 查询未纳入超时、TLS 首次握手耗时、长连接复用掩盖连接问题、流式接口持续有数据导致读超时失效、客户端取消未向下游传播、异步任务超时后仍在后台执行。gRPC deadline 传播能让下游知道剩余时间并在超时后取消工作。",
