      "回滚（Rollback）是在发布、配置、数据迁移或依赖变更出现异常时，把系统恢复到上一个稳定状态的工程能力。它的价值是缩短故障影响时间，让团队在错误率、延迟或业务指标异常时快速止损。",
      "部署回滚通常包含触发、判定、执行、验证和复盘五步。触发来自告警、灰度分析或人工确认；判定要看影响范围和数据风险；执行可能是切回旧镜像、旧配置、旧流量权重或旧功能开关；验证要观察错误率、延迟、饱和度、日志和业务指标；复盘记录根因和改进项。",
      "不同系统的回滚对象不同。Kubernetes 可以通过 Deployment revision 回到历史版本，CodeDeploy 和 Cloud Deploy 支持失败部署后的重新部署或目标回退，Argo Rollouts 支持渐进式发布中的快速回退；配置系统和功能开关常用于秒级关闭新路径。",
      "回滚最难的部分常在数据。代码可以切回旧版本，数据库 schema、消息格式、缓存 key 和外部副作用需要提前做兼容设计。扩展-迁移-切换-收缩（expand and contract）可以让新旧版本并行运行，降低数据回滚成本。",
      "自动回滚要绑定清晰阈值。错误率突增、P95/P99 延迟恶化、健康检查失败、实例不可用、队列积压、关键业务指标下降或错误预算快速消耗，都可以成为暂停发布或执行回退的信号。",
      "特殊情况包括部分成功、长事务、异步任务、重复消息、缓存污染和不可逆外部调用。支付、发券、库存扣减、邮件短信这类副作用要用幂等、补偿任务、对账和人工审批配合回滚。",
      "常见误区是只准备代码版本回退，忽略配置、数据、依赖、流量入口和客户端兼容。可用的回滚方案需要在发布前演练，明确负责人、命令、权限、耗时、验证指标和失败后的升级路径。",
