    engineeringValue: "在多实例环境中保护临界资源和跨进程互斥操作。",
    explanation: [
      "分布式锁（Distributed Lock）是在多个进程、多个实例或多个节点之间协调同一份资源访问的机制。它常用于定时任务抢占、缓存重建、库存扣减保护、订单状态流转和跨实例互斥执行。",
      "一把可用的分布式锁至少要描述资源 key、持有者标识、租约或过期时间、获取条件、释放条件和失败策略。获取锁要保证同一时刻只有一个有效持有者；释放锁要校验持有者；租约到期要避免永久占用；临界区要控制在锁有效期内。",
      "常见实现有三类：Redis 基于 SET NX PX 和随机 value 提供轻量互斥；ZooKeeper/Curator 基于临时顺序节点和 watch 实现排队锁；etcd 基于 lease、revision 和事务语义实现锁。方案选择取决于一致性要求、延迟预算、运维成本和业务损失。",
      "分布式锁的核心边界是网络分区、进程暂停、时钟漂移、GC 停顿和锁过期。客户端以为自己仍持有锁时，服务端租约可能已经过期；新的客户端可能已经获得锁；旧持有者继续写入会覆盖新结果，这时需要栅栏令牌（fencing token）或下游版本校验保护资源。",
      "Redis Redlock 适合讨论锁安全性的取舍。Redis 官方给出多节点 Redlock 流程，Kleppmann 强调强一致写入场景需要 fencing token 或线性一致存储，antirez 从工程故障模型角度解释 Redlock 的适用空间。落地时要按业务后果选择锁强度。",
      "分布式锁还要配合幂等和事务。锁只能减少并发进入临界区的概率和范围，业务写入仍需要唯一约束、版本号、幂等键、状态机校验或事务保护，防止重复执行和旧请求覆盖。",
      "可观测性是分布式锁的生命线。需要记录加锁成功率、等待时间、持锁时间、续期次数、释放失败、租约过期、竞争队列长度和业务资源 key；高竞争资源要设置告警，并评估锁粒度是否过粗。",
      "常见误区是把分布式锁当成数据库事务替代品。成熟设计会先缩小临界区和锁粒度，再明确超时、续期、释放、补偿和降级路径，并通过压测验证进程崩溃、网络抖动、服务重启和下游慢写等场景。",
      "参考来源：本讲解参考 Redis distributed locks、etcd locks、ZooKeeper recipes、Apache Curator shared reentrant lock、Martin Kleppmann 与 antirez 关于 Redlock 的讨论、OpenTelemetry 可观测性资料，以及 JavaGuide 中文工程资料。",
    ],
