    id: "lua-unlock",
    zh: "Lua 解锁",
    en: "Lua Unlock",
    area: "consistency",
    difficulty: "medium",
    engineeringValue: "保证校验锁持有者和删除锁两个动作的原子性。",
    explanation: [
      "Lua 解锁是 Redis 锁释放阶段的标准做法，核心目标是把“确认锁仍属于当前客户端”和“删除锁 key”放进同一次 Redis 脚本执行里。这样可以避免客户端先 GET 再 DEL 时被其他客户端插入操作。",
      "典型脚本是：`if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end`。`KEYS[1]` 是锁 key，`ARGV[1]` 是加锁时写入的 uniqueValue；返回 1 表示释放成功，返回 0 表示锁已过期、已被别人持有或 key 已消失。",
      "Lua 脚本在 Redis 中以单线程命令序列执行，脚本运行期间其他命令无法插入这段校验和删除逻辑。EVAL 负责直接执行脚本，生产系统常用 SCRIPT LOAD + EVALSHA 缓存脚本，减少重复传输脚本文本。",
      "Lua 解锁解决的是误删风险。客户端 A 的锁过期后，客户端 B 获取同一个 key；此时 A 如果直接 DEL，会删除 B 的锁。脚本先比对 value，value 对上才删除，value 对不上返回 0。",
      "特殊情况包括脚本超时、Redis 主从切换、客户端重试和锁已自然过期。释放失败通常要记录日志和指标；返回 0 需要按正常边界处理，因为锁可能已经过期，业务补偿和幂等逻辑要能吸收重复执行。",
      "脚本要保持短小、确定和低成本。解锁脚本只做 GET、比较和 DEL，避免循环、跨 key 扫描、外部依赖和复杂计算；Redis Cluster 场景下脚本访问的 key 要遵守同槽位规则。",
      "常见误区是直接 DEL、先 GET 后 DEL、把 value 写成固定常量，或在 finally 中无条件删除锁。正确做法是每次加锁生成请求级唯一 value，并把这个 value 贯穿续期、解锁和日志追踪。",
      "参考来源：本讲解参考 Redis distributed locks 中的安全释放脚本，Redis Lua scripting、EVAL、SCRIPT、GET、DEL 和 SET 命令文档。",
    ],
