    id: "acid",
    zh: "ACID",
    en: "ACID",
    area: "consistency",
    difficulty: "medium",
    engineeringValue: "定义数据库事务的原子性、一致性、隔离性和持久性。",
    explanation: [
      "ACID 是数据库事务的四个基本性质：Atomicity 原子性、Consistency 一致性、Isolation 隔离性、Durability 持久性。它描述的是数据库如何在提交、回滚、并发和故障恢复中保护数据正确性。",
      "原子性表示事务内操作以整体为单位生效。转账时扣减 A 账户和增加 B 账户要一起提交；中间任一步失败，数据库通过回滚机制撤销已做的未提交修改。",
      "一致性表示事务执行前后，数据都满足约束和业务不变量。数据库可以检查主键、唯一约束、外键、CHECK、触发器等规则；更复杂的业务一致性需要应用在事务边界里显式校验。",
      "隔离性表示并发事务之间的中间状态受到控制。隔离级别决定一个事务能看到另一个事务的哪些变化，也影响脏读、不可重复读、幻读、锁等待、死锁和吞吐量。",
      "持久性表示事务提交成功后，结果能够在数据库崩溃、进程重启或系统恢复后保留下来。实现通常依赖 redo log、WAL、刷盘策略、复制确认和崩溃恢复流程。",
      "ACID 是数据库提供的能力边界。它通常覆盖单数据库或单资源管理器内的事务；跨服务、跨数据库、消息队列、缓存和外部 API 的一致性还需要事务外盒、Saga、幂等、补偿和对账。",
      "特殊情况包括弱隔离级别、长事务、DDL、复制延迟和异步副作用。事务提交并不代表搜索索引、缓存、消息消费者和外部系统已经同步完成，因此系统设计要区分数据库内一致性和系统级一致性。",
      "常见误区是把一致性理解成“所有副本立即一样”，或认为使用事务后所有并发问题都消失。ACID 需要结合具体数据库、存储引擎、隔离级别、日志刷盘和应用事务边界一起判断。",
      "排查 ACID 相关问题时，先看事务隔离级别、约束是否完整、提交/回滚日志、redo/WAL 刷盘配置、锁等待、死锁、长事务和崩溃恢复记录，再把问题映射到四个性质中的哪一类。",
      "参考来源：本讲解参考 IBM ACID properties、MySQL InnoDB and the ACID Model、PostgreSQL Transactions 与 Transaction Isolation、MySQL InnoDB transaction model、MySQL COMMIT/ROLLBACK、SQL Server locking and row versioning，以及 OpenTelemetry 可观测性资料。",
    ],
