    id: "isolation-level",
    zh: "隔离级别",
    en: "Isolation Level",
    area: "consistency",
    difficulty: "hard",
    engineeringValue: "控制并发事务之间可见性，平衡一致性和性能。",
    explanation: [
      "隔离级别（Isolation Level）定义并发事务之间可以看到哪些数据变化。它是 ACID 中 Isolation 的具体落地，用来在一致性、吞吐量、锁等待和死锁概率之间做取舍。",
      "SQL 标准常见级别包括 Read Uncommitted、Read Committed、Repeatable Read 和 Serializable。级别越强，数据库越倾向于阻止并发异常；代价通常是更多锁、更多冲突检测、更高延迟或更频繁重试。",
      "要理解隔离级别，先抓三类现象：脏读是读到未提交数据；不可重复读是同一事务两次读取同一行看到不同已提交版本；幻读是同一事务两次范围查询看到新增或消失的行。",
      "Read Committed 通常只读取已提交数据，每条语句可能看到新的已提交版本，适合很多在线业务。Repeatable Read 通常让同一事务内一致性读看到稳定快照，MySQL InnoDB 默认使用该级别，并结合 next-key lock 处理范围写冲突。",
      "Serializable 提供最强隔离语义，常通过锁或序列化冲突检测让事务表现得像串行执行。它适合金融清算、强约束库存和账务等关键路径，但需要处理等待、冲突失败和重试。",
      "不同数据库实现差异很大。PostgreSQL 的 Repeatable Read 基于快照隔离并会避免标准里某些幻读现象；MySQL InnoDB 的快照读、当前读、间隙锁和 next-key lock 会影响实际行为；SQL Server 还提供 snapshot isolation 和 read committed snapshot。",
      "工程上选择隔离级别要从业务异常容忍度出发。统计报表可以接受较弱一致性，余额扣减、库存扣减、唯一业务流转要配合唯一约束、条件更新、乐观锁、悲观锁或串行化事务。",
      "排查隔离级别问题时，看事务隔离设置、SQL 是否走索引、快照读与当前读差异、锁等待、死锁日志、版本存储膨胀、长事务和重试失败。线上变更隔离级别前要用并发压测验证业务不变量。",
      "常见误区是按名称直接推断实际行为。隔离级别的真实效果取决于数据库实现、存储引擎、SQL 类型、索引、锁模式和 MVCC 机制，面试和设计都要结合具体数据库说明。",
      "参考来源：本讲解参考 PostgreSQL Transaction Isolation、MySQL InnoDB Transaction Isolation Levels 与 transaction model、SQL Server SET TRANSACTION ISOLATION LEVEL、locking/row versioning 与 snapshot isolation、MySQL ACID 文档，以及 OpenTelemetry 可观测性资料。",
    ],
