    id: "change-data-capture",
    zh: "CDC",
    en: "Change Data Capture",
    area: "consistency",
    difficulty: "hard",
    engineeringValue: "从数据库变更日志捕获事件，降低业务代码侵入。",
    explanation: [
      "CDC（Change Data Capture）从数据库变更日志中捕获插入、更新、删除等事实事件，再发布给消息队列、搜索索引、缓存、数据仓库或下游服务。MySQL 常见来源是 binlog，PostgreSQL 常见来源是 WAL 逻辑解码。",
      "CDC 的价值是复用数据库提交事实。业务写入只关注本地事务，CDC 组件异步读取提交后的变更，减少业务代码里手工发事件、同步下游和维护双写逻辑的负担。",
      "启动 CDC 通常会先做快照，再从日志位点继续增量读取。快照负责把已有数据补齐，日志位点负责保证快照之后的变更继续衔接；位点、GTID、LSN 或 offset 必须持久化，便于故障恢复后续读。",
      "CDC 的事件顺序通常以数据库日志顺序为基础。单表、单分区或同一主键的顺序相对容易维护，跨表、跨库和跨分区的全局业务顺序需要通过事务元数据、版本号、聚合 id 或状态机额外约束。",
      "CDC 也会产生重复事件。连接器重启、offset 提交延迟、broker 重试和消费者失败都可能让同一变更再次出现；消费者要使用主键、事件 id、版本号或去重表实现幂等处理。",
      "Schema 演进是 CDC 的高频风险。新增字段、字段类型变化、字段删除、表拆分和枚举扩展都会影响下游解析；事件应带 schema 版本，并通过 Schema Registry 或兼容性规则管理消费者升级。",
      "CDC 和事务外盒经常组合使用。普通表 CDC 会把所有数据变更都变成技术事件，Outbox Router 只转发业务设计过的 outbox 事件，能更好控制事件名称、载荷、聚合 id 和下游契约。",
      "特殊情况包括快照期间数据持续变化、DDL 与 DML 交错、binlog/WAL 保留不足、连接器权限不足、主从切换、日志压缩、超大事务、热点表高吞吐和下游积压。每一种都需要明确恢复和补数方案。",
      "监控 CDC 要看源库日志滞后、连接器存活、offset 提交、快照进度、事件发送速率、失败重试、DLQ 数量、消费者延迟和 schema 兼容性错误。延迟指标要按业务可接受时限设置告警。",
      "参考来源：本讲解参考 Debezium MySQL Connector、PostgreSQL Connector、Outbox Event Router、Incremental Snapshots、microservices.io Transaction Log Tailing、Confluent Schema Evolution，以及 PostgreSQL/MySQL 事务资料。",
    ],
    typicalProblems: [
      "CDC 解决什么数据库变更传播问题",
      "binlog、WAL、LSN、offset 分别承担什么作用",
      "CDC 启动时为什么需要快照和增量衔接",
      "CDC 怎样保证同一主键或同一聚合的事件顺序",
      "连接器重启为什么会产生重复事件",
      "CDC 消费端为什么必须幂等",
      "DDL 和 schema 演进怎样影响下游消费者",
      "CDC 与事务外盒组合有什么价值",
      "binlog/WAL 保留不足会造成什么风险",
      "线上监控 CDC 应该看哪些延迟和错误指标",
    ],
    practiceAdvice: [
      "为 CDC 记录并备份日志位点、连接器配置、快照进度和 schema 版本，保证故障后可恢复",
      "下游消费者按主键、事件 id 或版本号做幂等，并为重复、乱序和补数建立处理流程",
      "监控源库日志滞后、连接器状态、offset 提交、事件积压、DLQ 数量和 schema 兼容性错误",
    ],
    prerequisites: ["transactional-outbox", "database-transaction", "message-queue"],
    related: ["event-driven", "idempotency", "deduplication", "dead-letter", "log-aggregation"],
    order: 68,
