    id: "consumer-group",
    zh: "消费组",
    en: "Consumer Group",
    area: "messaging",
    difficulty: "medium",
    engineeringValue: "支持多实例并行消费同一类消息，提升吞吐和可用性。",
    explanation: [
      "消费组是一组共同消费同一类消息的消费者实例。队列或日志系统把消息分配给组内实例处理，从而提升吞吐、支持水平扩容，并在实例故障时把分配关系转交给存活实例。",
      "在 Kafka 中，同一个 consumer group 里的一个分区同一时刻只分配给一个消费者。消费者数量提升到分区数以后，并行度会达到上限；继续增加实例主要提供热备和弹性空间。",
      "offset 是消费组的进度记录。自动提交配置简单，手动提交能把业务处理成功和 offset 推进绑定起来；提交过早会丢处理机会，提交过晚会增加重复消费概率。",
      "Rebalance 会在消费者加入、离开、心跳超时、订阅 topic 变化或分区数变化时触发。重平衡期间分区会重新分配，消费者可能短暂停顿，并出现重复处理、局部延迟上升和缓存失效。",
      "消费组的吞吐由分区数、单条处理耗时、批量拉取大小、消费者线程模型和下游容量共同决定。只加消费者数量会遇到分区上限、数据库瓶颈或下游限流。",
      "顺序性通常按分区保证。同一个业务键要进入同一个分区，消费者才能按该键顺序处理；跨分区全局顺序成本高，常见做法是用业务键分区并把顺序范围缩小到单个聚合或账户。",
      "消费组设计要配合幂等。重复投递、重试、rebalance、超时恢复和手动 seek 都可能让同一消息再次执行，消费者应使用 messageId、业务唯一键或状态机约束来去重。",
      "关键参数包括 group.id、enable.auto.commit、auto.offset.reset、max.poll.records、max.poll.interval.ms、session.timeout.ms、heartbeat.interval.ms 和分区分配策略。参数要按处理耗时和故障恢复目标调优。",
      "特殊情况包括慢消费者拖高 consumer lag、长时间处理触发 rebalance、同组实例订阅 topic 不一致、分区热点导致局部积压、消费者扩容超过分区数、offset reset 造成重放或跳过。",
      "参考来源：本讲解参考 Apache Kafka Documentation 与 Consumer Configs、Confluent Kafka Consumer 与 Consumer Design、Confluent Kafka Rebalancing、RabbitMQ 文档和 Amazon SQS FIFO/Standard 队列资料。",
    ],
