    id: "dead-letter",
    zh: "死信队列",
    en: "Dead Letter Queue",
    area: "messaging",
    difficulty: "medium",
    engineeringValue: "隔离持续失败消息，保护正常消费链路。",
    explanation: [
      "死信队列用于接收无法被正常消费链路继续处理的消息。它把持续失败、过期、被拒绝或超过投递次数的消息隔离起来，保护主队列吞吐，并给排障和补偿留下证据。",
      "进入死信的常见条件包括消费者显式拒绝、消息 TTL 到期、队列长度超限、达到最大接收次数、schema 解析失败、业务校验失败和下游依赖长期不可用。不同消息系统的触发条件和字段名会有差异。",
      "RabbitMQ 使用 Dead Letter Exchange 承接死信路由，消息可因 rejected/nack 且 requeue=false、TTL 过期、队列超长等原因进入 DLX。路由键和绑定关系要单独设计，避免死信继续回到原队列。",
      "Amazon SQS 通过 redrive policy 配置死信队列和 maxReceiveCount。消息接收次数达到阈值后进入 DLQ，后续可以通过 redrive 任务把消息移回源队列或其他目标队列。",
      "Google Pub/Sub 使用 dead-letter topic 和最大投递尝试次数，Azure Service Bus 内置 DLQ 并记录 dead-letter reason。平台字段能帮助定位失败原因，但业务错误上下文仍然需要消费者主动记录。",
      "Kafka 没有统一的内置 DLQ 语义，常见做法是消费者捕获不可恢复错误后写入专门的 dead-letter topic，同时保留原 topic、partition、offset、key、headers、异常类型和失败时间。",
      "死信队列需要配套可观测性。至少监控死信数量、进入速率、失败原因分布、消息年龄、重放成功率和同一业务键重复失败次数，并把告警分成 schema、业务校验、下游依赖和权限配置几类。",
      "重放死信前要先修复根因。重放流程应支持按原因、时间、业务键、消息 id 过滤，控制速率，保留审计记录，并确保消费者具备幂等能力，避免补偿时产生重复副作用。",
      "特殊情况包括死信队列无人消费、死信无限堆积、重放后再次失败形成循环、FIFO 队列顺序被阻塞、敏感字段在死信中长期保留、错误分类过粗导致排障困难。",
      "参考来源：本讲解参考 RabbitMQ Dead Letter Exchanges 与 Negative Acknowledgements、Amazon SQS Dead-letter queues、Google Pub/Sub Dead-letter topics、Azure Service Bus DLQ、Kafka Consumer Configs 和 Confluent Kafka Consumer 资料。",
    ],
