    id: "poison-message",
    zh: "毒丸消息",
    en: "Poison Message",
    area: "messaging",
    difficulty: "medium",
    engineeringValue: "识别无法成功处理的异常消息，避免反复消耗消费者资源。",
    explanation: [
      "毒丸消息是每次投递都会稳定触发失败的消息。它可能格式损坏、schema 版本不兼容、字段语义非法、业务状态已经失效，或触发消费者代码缺陷。",
      "毒丸消息的危险在于重复消耗同一段消费能力。消费者不断拉取、失败、回滚和重试，会拖慢同分区或同队列的后续消息，严重时让整个消费组出现积压。",
      "识别毒丸消息要区分临时失败和确定性失败。网络抖动、下游限流和短暂超时适合退避重试；schema 解析失败、必填字段缺失、非法枚举、权限永久拒绝和业务前置状态缺失更接近毒丸消息。",
      "治理毒丸消息的基本动作是设置最大重试次数。超过阈值后把消息转入死信队列或 dead-letter topic，并记录原始消息、失败原因、异常栈、重试次数、消费者版本和首次失败时间。",
      "RabbitMQ 可以通过 nack/reject 且 requeue=false 配合 Dead Letter Exchange 隔离毒丸消息。SQS 使用 maxReceiveCount 触发 DLQ，Pub/Sub 使用最大投递尝试次数和 dead-letter topic，Azure Service Bus 会把无法处理的消息放入 DLQ。",
      "Kafka 常见做法是在消费者代码中捕获不可恢复异常，写入 dead-letter topic 后提交原 offset，让主消费链路继续前进。写入 DLQ 和提交 offset 要设计成可恢复流程，避免错误消息卡住分区。",
      "毒丸消息需要保留重放入口。修复 schema、数据或代码后，可以按消息 id、业务键、失败类型和时间窗口筛选重放；重放前要先验证消费者幂等，防止重复扣款、重复发货或重复通知。",
      "常见误区是把所有失败都无限重试。合理做法是按错误类型分层：可恢复错误退避重试，不可恢复错误进入死信，需要人工判断的错误进入待处理队列并触发告警。",
      "特殊情况包括毒丸消息在 FIFO 队列中阻塞后续消息、重放后再次进入死信形成循环、错误分类太宽导致正常消息被隔离、死信中保存敏感数据和消费者版本升级后旧消息解析规则变化。",
      "参考来源：本讲解参考 Enterprise Integration Patterns Dead Letter Channel、RabbitMQ Dead Letter Exchanges 与 Negative Acknowledgements、Amazon SQS DLQ、Google Pub/Sub dead-letter topics、Azure Service Bus DLQ、Kafka Consumer Configs 和 Confluent Kafka Consumer 资料。",
    ],
