    id: "idempotency",
    zh: "消费幂等",
    en: "Consumer Idempotency",
    area: "messaging",
    difficulty: "medium",
    engineeringValue: "让重复投递和重试场景保持业务结果一致。",
    explanation: [
      "消费幂等是让同一条消息被处理一次或多次时，最终业务结果保持一致。消息系统常提供至少一次投递，网络抖动、消费者重启、ack 丢失、offset 提交失败和重试都会带来重复执行。",
      "幂等的核心是先定义业务唯一性。订单创建可以用 orderId，支付入账可以用 paymentId，库存扣减可以用 reservationId，通知发送可以用 notificationId；messageId 可作为辅助去重键。",
      "最稳的做法是把去重记录和业务写入放在同一个事务里。消费者先尝试插入 processed_message(message_id, consumer_name)，插入成功后执行业务变更并提交；唯一键冲突表示消息已处理。",
      "ack 或 offset 提交应该发生在业务处理成功之后。先 ack 再写业务会导致失败后消息丢失处理机会；先写业务再 ack 可能重复投递，因此消费者需要幂等处理来吸收重复。",
      "幂等可以通过数据库唯一约束、状态机条件更新、乐观锁版本号、Redis 去重窗口和业务自然键实现。关键业务优先使用强一致存储，缓存去重适合可容忍短窗口重复的场景。",
      "Kafka 的事务和 exactly-once 语义主要覆盖 Kafka 内部读写链路与 offset 提交组合。消费者写外部数据库、调用第三方接口或发送邮件时，仍然需要业务幂等键和补偿设计。",
      "SQS FIFO 提供消息去重 ID 和消息组顺序能力，但去重窗口有限；RabbitMQ 的确认机制保证消息交付确认，消费者异常重连后仍可能 redelivery。业务侧幂等依然是最后防线。",
      "幂等处理要记录结果。重复消息到来时可以直接返回已处理结果、跳过副作用、补齐缺失的下游动作，或进入人工核对队列；这取决于业务操作能否安全重放。",
      "特殊情况包括同一 messageId 被多个业务语义复用、去重表 TTL 太短、Redis 去重先写后业务失败、外部接口缺少幂等键、并发重复消息同时进入、乱序消息让状态机倒退。",
      "参考来源：本讲解参考 Microservices.io Idempotent Consumer Pattern、RabbitMQ Reliability 与 Confirms、Apache Kafka Consumer Configs 与 Transactions、Confluent Exactly-Once Semantics、Amazon SQS FIFO 队列和 Stripe Idempotent Requests 资料。",
    ],
