      "在 Cache Aside 中，读路径可能回填旧值，写路径可能删除缓存失败。缓存一致性设计要围绕这些窗口建立保护：TTL 兜底、写后删除、延迟二次删除、版本检查和补偿任务。",
      "常见写策略是先更新数据库，再删除缓存。数据库是权威源，删除缓存让下一次读取回源新值；直接更新缓存容易遇到并发覆盖、部分字段遗漏和双写失败问题。",
      "并发读写会制造脏缓存。读请求先从数据库读到旧值，写请求随后更新数据库并删除缓存，读请求最后把旧值写回缓存；延迟双删、回填前校验版本和缩短 TTL 都能降低风险。",
      "删除缓存失败需要可靠补偿。关键数据可以把缓存失效事件写入 outbox，事务提交后异步删除 Redis；也可以通过 CDC 监听数据库变更，按主键删除或刷新相关缓存。",
      "TTL 是最终兜底。即使删除失败，缓存也会在 TTL 到期后自然失效；TTL 应按业务容忍度设置，价格、库存、权限类数据通常需要更短陈旧窗口和更强校验。",
      "一致性级别要分业务。商品详情、文章内容可以接受秒级或分钟级陈旧；余额、库存、权限、风控结果需要读主库、版本校验、短 TTL 或直接避开缓存。",
      "校验与观测很重要。可以抽样比对缓存和数据库，记录缓存版本、更新时间、命中来源、删除失败率、补偿延迟、脏读发现数和回源压力。",
      "特殊情况包括一个数据库变更影响多个缓存 key、本地缓存和 Redis 双层缓存失效顺序不同、批量更新造成删除风暴、事务回滚后误删缓存、读写分离延迟导致回填旧值。",
      "参考来源：本讲解参考 Redis Cache Aside、Redis Cache Consistency、Redis EXPIRE、Redis Observability、AWS Database Caching Strategies Using Redis、Microsoft Azure Cache-Aside Pattern、阿里云缓存一致性文章和 Microservices.io Transactional Outbox Pattern。",
