    id: "logical-expire",
    zh: "逻辑过期",
    en: "Logical Expiration",
    area: "cache",
    difficulty: "medium",
    engineeringValue: "热点缓存过期后先返回旧值，再异步刷新。",
    explanation: [
      "逻辑过期是把过期时间作为业务字段放进缓存值里，而不是完全依赖 Redis 物理 TTL。缓存命中后先判断 logicalExpireAt，未过期直接返回，已过期则返回旧值并触发后台刷新。",
      "它适合热点 key 和昂贵回源场景。热点 key 物理过期会引发大量请求同时回源；逻辑过期让请求继续拿到旧值，把刷新动作交给少量后台任务或拿到锁的请求。",
      "缓存值通常包含 data、logicalExpireAt、version、refreshing 标记或刷新锁信息。Redis 物理 TTL 可以设置得更长，作为兜底清理，逻辑过期控制新鲜度。",
      "典型流程是读缓存命中后检查 logicalExpireAt；若仍在新鲜期，直接返回；若进入陈旧可服务期，先返回旧值，再尝试获取刷新锁，拿锁者异步回源并覆盖缓存。",
      "逻辑过期本质接近 stale-while-revalidate：用户先得到旧内容，系统在后台刷新。它用短时间陈旧换取稳定延迟和数据库保护，适合商品详情、配置、榜单和内容页。",
      "陈旧窗口要按业务容忍度设置。价格、库存、权限、风控结果等强实时数据需要更短窗口、版本校验或直接读权威源；内容展示、排行榜和推荐结果可以接受更长窗口。",
      "刷新失败时要继续服务旧值或降级，同时记录告警和重试。需要设置最大陈旧时间，超过上限后可以强制同步回源、返回降级内容或限流。",
      "逻辑过期要配合互斥刷新。多个请求发现过期时，只有一个请求拿锁刷新，其余请求继续读旧值，避免后台刷新也变成并发回源风暴。",
      "特殊情况包括旧值长期未刷新、后台刷新任务丢失、逻辑过期时间和物理 TTL 配置冲突、旧值超出业务容忍窗口、版本回退覆盖新值和缓存值过大导致刷新慢。",
      "参考来源：本讲解参考 Redis Cache Aside、Redis Caching Use Case、Redis EXPIRE、Redis Observability、Redis Distributed Locks、Redis SET、AWS CloudFront stale-while-revalidate 和 AWS Database Caching Strategies Using Redis 资料。",
    ],
