      "参考来源：本讲解参考 OWASP Logging、NIST SP 800-92、OpenTelemetry Logs Data Model、OpenTelemetry Semantic Conventions、Google Cloud Structured Logging、Logback MDC、Google Cloud Audit Logs 和 OpenTelemetry Observability Primer。",
