    id: "structured-log",
    zh: "结构化日志",
    en: "Structured Logging",
    area: "observability",
    difficulty: "medium",
    engineeringValue: "让日志可检索、可聚合、可自动化分析。",
    explanation: [
      "结构化日志是把日志事件写成固定字段的记录，常见格式是 JSON 或 key-value。它把一段自然语言拆成可查询字段，让日志系统可以按服务、用户、traceId、错误码、路由和状态码快速筛选与聚合。",
      "一条结构化日志通常包含时间、级别、消息、服务名、环境、版本、实例、traceId、spanId、requestId、主体、动作、资源、结果、错误码和耗时。字段越稳定，检索和仪表盘复用价值越高。",
      "统一 schema 是关键。团队可以参考 OpenTelemetry Logs Data Model、Semantic Conventions 或 Elastic Common Schema，把 http.method、http.route、status_code、service.name、event.action 这类字段固定下来，降低跨服务查询成本。",
      "结构化日志和 MDC 很搭。入口层把 traceId、tenantId、userId、requestId 放进上下文，日志框架自动带出这些字段，业务代码只需要记录事件本身，排障时可以沿同一组关联字段检索。",
      "字段类型要长期稳定。statusCode 一直用数字，duration_ms 一直用数字，errorCode 一直用字符串；同名字段类型漂移会影响索引、聚合和告警规则。",
      "高基数字段要谨慎进入索引。用户 ID、订单号、请求 URL 原文和异常堆栈适合放在日志内容或低成本字段中，服务名、环境、路由模板、状态码、错误码更适合做常用筛选字段。",
      "安全上要处理日志注入和敏感字段。用户输入写入日志前要转义换行和控制字符，密码、令牌、密钥、证件号和隐私数据要脱敏、哈希或只保留末尾片段。",
      "特殊情况包括多语言服务字段命名不一致、嵌套 JSON 过深导致索引膨胀、字段缺失让告警失效、异常堆栈过长被截断、批量日志导致事件边界混乱、日志 schema 变更缺少兼容期。",
      "落地时先选 20 到 30 个核心字段，覆盖请求、错误、审计和业务事件；再为高频查询建立索引和仪表盘。字段扩展要像 API 变更一样评审，确保下游查询和告警能持续工作。",
      "参考来源：本讲解参考 Google Cloud Structured Logging、OpenTelemetry Logs Data Model、OpenTelemetry Semantic Conventions、Elastic Common Schema、OWASP Logging、NIST SP 800-92、Logback MDC 和 Google Cloud Audit Logs。",
    ],
