      "典型链路是应用输出结构化日志，Agent 或 Sidecar 采集文件、stdout 或 journald，再经过 Collector、Fluent Bit、Logstash 等组件解析、补字段、过滤、采样、批量发送，最后进入 Elasticsearch、Loki、Cloud Logging 或对象存储。",
      "采集层要关注可靠性和背压。日志高峰、网络抖动、后端写入变慢时，Agent 需要缓冲、重试、限速和丢弃策略；本地磁盘缓冲可以降低短时故障造成的日志丢失。",
      "处理层负责把日志变成可查询数据。常见动作包括解析 JSON、提取 traceId、补 service.name/environment/version、脱敏敏感字段、统一时间戳、按级别或路由过滤高频噪声。",
      "存储层要围绕查询模式设计。Elasticsearch 更强调字段索引和全文检索，Loki 更强调低基数标签和按日志流查询；选择字段索引或标签时，要优先服务高频排障查询和告警关联。",
      "成本主要来自日志量、索引字段、标签基数、保留周期和副本数。用户 ID、订单号、完整 URL、异常堆栈等高基数字段要谨慎索引，适合放在正文或低成本存储中。",
      "日志聚合还要支持合规和审计。关键审计日志、错误日志和安全事件通常需要更长保留周期、更严格访问控制和完整性保护，普通调试日志可以用较短保留周期。",
      "特殊情况包括采集 Agent 占满节点资源、时间戳使用采集时间导致排序错误、多行堆栈解析失败、容器重启导致文件偏移丢失、字段 schema 变更打断查询、标签基数暴涨拖垮 Loki 或索引集群。",
      "落地时要从排障问题反推设计：按 traceId 查一次请求，按 service 和 errorCode 聚合错误，按版本对比发布前后，按租户或区域定位影响面。能支撑这些查询，日志聚合才真正可用。",
      "参考来源：本讲解参考 OpenTelemetry Collector、Collector Processors、Fluent Bit Concepts、Fluent Bit Stream Processing、Logstash Introduction、Grafana Loki Labels、Elastic Common Schema 和 Google Cloud Structured Logging。",
