      "在生产架构里，应用日志通常先由 Filebeat、Fluent Bit 或 Collector 采集，再进入 Logstash 做解析、过滤、脱敏和字段补齐，最后写入 Elasticsearch 的 index 或 data stream，由 Kibana 供排障和分析使用。",
