      "Logstash 的价值在于管道处理。输入、过滤器和输出可以把多来源日志统一成同一 schema，完成 grok 解析、JSON 解析、字段重命名、脱敏、采样、路由和失败事件处理。",
      "Kibana 常用于 Discover 检索、Dashboard 展示、Lens 分析和告警调查。排障时通常按 traceId、service、environment、errorCode、route、host、version 和时间窗口逐步缩小范围。",
      "ELK 的主要风险是索引膨胀。字段过多、动态映射失控、高基数字段聚合、日志量突增、分片过多和保留周期过长，都会推高 JVM、磁盘、查询延迟和集群恢复成本。",
      "特殊情况包括 Logstash 管道阻塞导致采集延迟、映射冲突让写入失败、异常堆栈多行解析不完整、时间字段解析错误影响排序、Kibana 查询范围过大拖慢集群、审计日志访问权限过宽。",
      "落地 ELK 要先定义日志 schema、索引模板、生命周期、采集失败处理和常用查询面板，再接入服务。这样排障路径稳定，团队也能控制日志平台成本。",
