    id: "prometheus",
    zh: "Prometheus",
    en: "Prometheus",
    area: "observability",
    difficulty: "medium",
    engineeringValue: "提供时序指标采集、查询和告警基础能力。",
    explanation: [
      "Prometheus 是面向监控和告警的时序数据库与采集系统。它以指标名、标签和值组成时间序列，定期采集目标暴露的 /metrics，并用 PromQL 做查询、聚合和告警计算。",
      "Prometheus 默认采用 pull 模型：服务或 exporter 暴露 HTTP 指标端点，Prometheus 按 scrape_interval 拉取。这样服务端可以集中控制采集频率、目标发现和失败状态。",
      "数据模型的关键是 label。相同指标名加不同 label 会形成不同时间序列，例如 method、route、status_code、instance。标签让查询灵活，也会直接影响存储和查询成本。",
      "PromQL 是 Prometheus 的查询语言。常见写法包括用 rate 计算 Counter 增速，用 sum by 聚合维度，用 histogram_quantile 计算延迟分位数，用 offset 或 range vector 分析时间窗口。",
      "Recording rules 用来预计算常用或昂贵查询，把复杂 PromQL 结果写回新的时间序列。它适合高频仪表盘、SLO 计算和多维聚合，能减少重复查询成本。",
      "Alerting rules 用 PromQL 表达异常条件，并把告警发送给 Alertmanager。Alertmanager 负责分组、抑制、静默、去重和路由到值班渠道。",
      "Prometheus 适合监控服务健康、资源使用、依赖状态和业务指标。常见组合是 Prometheus 采集与存储，Grafana 展示仪表盘，Alertmanager 处理告警。",
      "主要边界是高基数和单机存储压力。用户 ID、订单号、完整 URL、traceId 进入 label 会制造大量时间序列；采集频率过高、保留周期过长和查询范围过大也会拖慢系统。",
      "特殊情况包括目标下线造成 stale series、服务重启导致 Counter 重置、抓取超时丢样、exporter 采集慢影响目标、直方图 bucket 设计不合理、告警表达式缺少 for 导致抖动。",
      "参考来源：本讲解参考 Prometheus Overview、Data Model、Querying Basics、Recording Rules、Alerting Rules、Alertmanager、Metric Naming 和 Histograms and Summaries。",
    ],
