      "SLO 告警更关注用户体验。常见做法是对错误预算消耗、错误率和尾延迟设置多窗口多燃速告警，既发现快速事故，也发现缓慢恶化。",
      "告警疲劳是核心风险。阈值过低、规则重复、缺少 for、告警没有负责人、通知渠道过多、低价值资源告警泛滥，都会让团队忽略真正重要的事件。",
      "特殊情况包括依赖故障造成告警风暴、自动扩容掩盖容量风险、黑盒监控正常但核心业务失败、告警恢复通知缺失、静默范围过大掩盖事故、时区和排班配置错误。",
      "落地时要把告警纳入值班流程。每条高优先级告警都要有 owner、severity、runbook、Dashboard、回滚或降级入口，并在复盘中持续修正规则。",
