      "它把稳定性目标转成可管理的工程资源。预算充足时，团队可以保持正常发布节奏；预算快速消耗时，团队应优先修复可靠性问题、收紧发布或启动降级。",
      "错误预算的计算依赖 SLI 分子和分母。例如请求成功率 SLI 可以用成功请求数除以总请求数，失败请求消耗预算；延迟 SLO 可以把超过阈值的请求计入坏事件。",
      "预算燃速表示错误预算被消耗的速度。高燃速说明当前故障会很快耗尽预算，适合触发快速告警；低燃速但持续存在的异常适合触发慢速告警。",
      "错误预算政策要提前约定动作。常见动作包括暂停高风险发布、要求变更评审、优先处理可靠性缺陷、增加容量、回滚问题版本、补充测试和完善告警。",
      "错误预算可以减少稳定性争论。产品团队看到预算充足时更容易接受继续交付，工程团队看到预算接近耗尽时更容易争取可靠性工作优先级。",
      "特殊情况包括 SLI 口径错误导致预算失真、低流量服务单次失败消耗比例过大、依赖故障反复消耗本服务预算、维护窗口是否计入预算、机器人流量和异常流量是否纳入分母。",
      "预算耗尽后的重点是恢复用户体验和降低再次消耗。团队应复盘预算消耗来源，按影响排序处理根因，并把行动项纳入发布门禁或容量计划。",
      "落地时要把错误预算展示在 Dashboard、周会和发布流程里。预算状态应能回答：剩余多少、燃速多快、哪个版本或依赖在消耗、是否需要暂停发布。",
      "参考来源：本讲解参考 Google SRE Service Level Objectives、Implementing SLOs、Example Error Budget Policy、Alerting on SLOs、Google Cloud SLO Monitoring、Burn Rate Alerts、Managing Incidents 和 Prometheus Alerting Rules。",
