      "在 W3C Trace Context 中，traceparent 头会携带 trace-id、parent-id、flags 等信息。trace-id 是 16 字节标识，通常表示为 32 个十六进制字符，全 0 值属于无效值。",
      "入口层通常生成 Trace ID，然后通过 HTTP header、RPC metadata、消息头或任务上下文传给下游。下游服务继承同一个 Trace ID，并为自己的局部操作创建新的 Span ID。",
      "Trace ID 要进入日志上下文。Java 常用 MDC 自动把 traceId 写入每条日志，其他语言也会使用类似上下文机制；这样工程师可以从错误日志直接跳到整条 trace。",
      "错误响应里带 Trace ID 很有价值。用户报错、客服工单或前端错误监控拿到 Trace ID 后，后端可以直接定位到对应请求，而不用凭时间和用户信息模糊搜索。",
      "Trace ID 和业务 Correlation ID 关注点不同。Trace ID 描述一次技术调用链，Correlation ID 可以描述订单、消息、批处理或跨多次请求的业务关联；两者经常同时出现。",
      "采样会影响 Trace ID 的排障能力。即使请求未被保留为完整 trace，也应尽量在日志里记录 Trace ID；错误、慢请求和核心业务路径适合提高采样保留概率。",
      "特殊情况包括网关未透传 traceparent、异步线程丢失上下文、消息消费重新生成 Trace ID、日志字段命名不统一、客户端传入伪造 Trace ID、Trace ID 被当作高基数指标标签。",
      "落地时要统一字段名，例如 trace_id 或 traceId，并在日志、trace、错误响应、消息头和前端监控中保持一致。这样排障链路才能跨系统跳转。",
      "参考来源：本讲解参考 W3C Trace Context、OpenTelemetry Tracing API、Context Propagation、Logging Trace Context、OpenTelemetry Traces、Sampling、Logback MDC 和 Google Cloud Structured Logging。",
