    id: "jaeger",
    zh: "Jaeger",
    en: "Jaeger",
    area: "observability",
    difficulty: "medium",
    engineeringValue: "提供分布式链路追踪存储、查询和可视化能力。",
    explanation: [
      "Jaeger 是分布式链路追踪后端，用来接收、存储、查询和展示 trace。它帮助工程团队按服务、操作名、耗时、错误和标签定位慢请求、依赖瓶颈和跨服务故障路径。",
      "Jaeger 的核心数据单位是 Trace 和 Span。Trace 表示一次端到端请求路径，Span 表示路径中的一个操作；多个 Span 通过父子关系组成调用树，展示服务之间的因果顺序和耗时分布。",
      "现代接入方式通常通过 OpenTelemetry SDK 或 Collector 生成 OTLP 数据，再导入 Jaeger。这样业务侧保持 OpenTelemetry 标准，Jaeger 专注查询、展示、存储和分析。",
      "架构上，Jaeger 包含接收遥测数据的 collector、查询 trace 的 query 服务、Web UI、存储后端，以及面向应用的采集入口。生产环境常把采集、查询和存储拆开部署，按写入量与查询量分别扩容。",
      "存储层决定保留时间、查询性能和成本。小规模环境可以使用内存或本地测试模式；生产环境通常接入 Elasticsearch、OpenSearch、Cassandra 或兼容后端，并配置索引、TTL、分片和归档策略。",
      "采样决定进入 Jaeger 的 trace 数量。头部采样适合在请求入口快速控制成本，尾部采样适合保留慢请求、错误请求和高价值链路；采样策略要结合流量、错误率、SLO 和后端容量一起设计。",
      "Service Performance Monitoring 可以从 trace 派生 RED 指标，即请求速率、错误率和耗时。它让团队从服务级指标跳到具体 trace，再从 trace 反查问题 Span。",
      "使用 Jaeger 排障时，常按 service、operation、duration、error、tag 和 traceID 检索。查到 trace 后，优先看入口耗时、最长 Span、错误事件、下游调用、重试和并发等待。",
      "特殊情况包括 trace 采样过低导致关键故障样本稀少、Span 名称高基数导致查询混乱、标签写入敏感信息、时钟偏移影响耗时判断、存储索引膨胀推高成本、Collector 写入瓶颈造成数据丢失。",
      "参考来源：本讲解参考 Jaeger Architecture、Terminology、Deployment、Sampling、Service Performance Monitoring、Performance Tuning、Migration to OpenTelemetry 和 OpenTelemetry OTLP 规范。",
    ],
