    engineeringValue: "验证服务与数据库、缓存、消息队列等依赖的协作正确性。",
    explanation: [
      "集成测试验证多个真实组件协作后的行为，例如 Web 层、应用服务、数据库、缓存、消息队列、鉴权中间件和序列化配置。它关注组件边界之间的数据流、事务、错误处理和配置组合。",
      "测试金字塔里，集成测试位于单元测试和端到端测试之间。它比单元测试更接近真实运行环境，比端到端测试反馈更快，适合覆盖服务内关键路径和核心依赖交互。",
      "后端集成测试常见入口包括 HTTP API、应用上下文、消息消费者、Repository、定时任务和后台作业。测试应从外部可观察行为断言结果，例如响应码、响应体、数据库状态、消息投递和副作用。",
      "依赖选择有三类：内存替身适合快速验证简单逻辑，真实服务适合验证协议和驱动行为，容器化依赖适合在 CI 中复现数据库、Redis、Kafka、RabbitMQ 等基础设施。Testcontainers 是这类测试的常见方案。",
      "测试数据要可重复、可隔离、可清理。常用做法包括每个用例独立事务、迁移脚本初始化 schema、固定 fixture、随机唯一业务 key、测试结束清理数据，以及把外部时钟和随机数注入为可控依赖。",
      "集成测试要覆盖成功、失败、超时、重试、幂等、权限、事务回滚和消息重复消费。只测 happy path 容易遗漏真实依赖的连接池、序列化、锁、隔离级别和网络异常。",
      "契约测试和集成测试可以配合。契约测试约束服务之间的接口承诺，集成测试验证当前服务和真实依赖组合后的运行行为；二者一起降低接口变更和依赖配置变更的风险。",
      "CI 中要控制稳定性和成本。集成测试通常分层运行：提交前跑核心集合，合并前跑完整集合；同时记录失败日志、容器日志、SQL、消息内容和随机种子，方便复现偶发失败。",
      "特殊情况包括测试环境与生产配置偏差、共享数据库导致用例互相污染、异步消息断言过早、固定端口冲突、容器启动慢、外部网络依赖抖动、时间相关断言不稳定、清理逻辑破坏排查证据。",
      "参考来源：本讲解参考 Microsoft ASP.NET Core Integration tests、Spring Boot Testing、Spring Boot Testcontainers、Testcontainers Java、Martin Fowler Practical Test Pyramid、Google Testing Blog Flaky Tests、Pact Contract Testing 和 Spring Cloud Contract。",
    ],
