    engineeringValue: "支撑表结构、数据模型和业务规则演进。",
    explanation: [
      "数据迁移是让数据库结构、历史数据和业务代码一起演进的工程过程。它覆盖建表改表、字段拆分合并、数据回填、索引调整、编码转换、租户迁移和历史数据修正。",
      "成熟迁移通常采用 expand/contract：先扩展 schema 兼容新旧代码，再双写或兼容读写，随后回填历史数据，验证一致性后切读，最后清理旧字段和旧逻辑。这个顺序能降低发布和回滚风险。",
      "版本化迁移工具把数据库变化写成可审计脚本，并按顺序应用到各环境。Flyway、Liquibase、Rails migrations 和 Django migrations 都强调迁移记录、顺序执行、环境一致和变更可追踪。",
      "在线迁移要控制锁、事务大小和资源消耗。大表加列、建索引、修改字段类型、更新全表和外键变更都可能影响写入延迟，MySQL Online DDL 等机制也需要结合具体操作、算法和锁级别评估。",
      "数据回填要分批、限速、可暂停、可重跑。常见做法是按主键范围或时间窗口扫描，记录游标和进度，使用幂等更新，控制每批事务大小，并把失败批次放入可重试队列。",
      "迁移校验要覆盖数量、校验和、抽样比对、业务不变量、读写差异、错误率、延迟和回滚指标。关键迁移应在影子读、双读或灰度流量中确认新旧结果一致。",
      "回滚设计要按阶段拆开看。扩展阶段通常容易回滚代码；切读和清理阶段需要保留旧数据、旧索引和兼容写入窗口；破坏性变更要等监控稳定、备份可用和恢复演练完成后执行。",
      "迁移和发布要配合特性开关、灰度、备份、集成测试与运行手册。上线前明确执行人、停止条件、回滚步骤、监控面板和数据修复脚本，上线后保留迁移日志和审计记录。",
      "特殊情况包括应用版本并存导致字段语义分裂、回填任务与在线流量争用资源、长事务阻塞复制、迁移脚本在不同环境顺序漂移、默认值触发全表重写、回滚脚本无法恢复已丢失语义。",
      "参考来源：本讲解参考 Prisma expand and contract、Liquibase rollback、Flyway Migrations、Flyway Migrate、Rails Active Record Migrations、Django Migrations、MySQL Online DDL 和 Martin Fowler Evolutionary Database Design。",
    ],
