    id: "queue-capacity",
    zh: "队列容量",
    en: "Queue Capacity",
    area: "resilience",
    difficulty: "medium",
    engineeringValue: "限制排队长度，防止请求堆积导致延迟失控。",
    explanation: [
      "队列容量是系统允许请求、任务或消息排队等待处理的上限。它把无限等待变成有界等待，让延迟、内存占用和故障影响范围都可控。",
      "容量设计要从等待时间预算倒推。若一个接口最多允许排队 200ms，处理能力是每秒 1000 个任务，那么可接受队列长度大致在 200 个任务量级，还要结合突发流量、服务时间分布和重试放大做压测校准。",
      "在线服务通常使用有界队列、线程池、连接池、信号量或 bulkhead 控制并发和排队。ThreadPoolExecutor 这类模型会把工作线程、队列和拒绝策略组合在一起，队列满时立即触发明确处理路径。",
      "队列满后的策略要提前定义：快速失败、返回 429/503、丢弃低优先级任务、降级、转入死信队列、重试排程或向上游传播背压。明确拒绝比无限排队更容易保护系统。",
      "队列容量和背压是一组配套机制。下游处理变慢时，队列增长就是压力信号；上游应降低发送速率、暂停消费、减少并发或触发负载丢弃，避免把慢故障放大成级联故障。",
      "队列容量也影响资源隔离。不同业务、不同优先级或不同下游依赖应使用独立队列和线程池，避免低价值流量占满共享队列，拖垮核心请求。",
      "监控重点包括队列长度、入队等待时间、处理耗时、拒绝数、超时数、工作线程利用率、消费速率、重试量和下游错误率。告警应基于持续饱和和等待时间，而只看瞬时队列长度容易误判突发流量。",
      "容量调优要通过压测验证。先测稳定吞吐和 P95/P99 服务时间，再模拟突发、下游变慢、重试风暴和消费者停顿，确认队列增长、拒绝策略和恢复速度符合预期。",
      "特殊情况包括队列过大掩盖故障并拉长尾延迟、队列过小误伤正常突发、FIFO 队列让慢任务阻塞短任务、重试任务占满队列、异步任务缺少超时导致永久堆积、内存队列在重启时丢失任务。",
      "参考来源：本讲解参考 Java ThreadPoolExecutor、BlockingQueue、RejectedExecutionHandler、AWS Load Shedding、Google SRE Handling Overload、Microsoft Bulkhead、Resilience4j Bulkhead 和 Go Pipelines。",
    ],
    typicalProblems: [
      "队列容量解决什么过载问题",
      "怎样根据等待时间预算估算队列长度",
      "有界队列和无界队列对延迟与内存有什么影响",
      "线程池、连接池、信号量和队列容量怎样配合",
      "队列满时应该采用哪些拒绝或降级策略",
      "队列容量和背压是什么关系",
      "不同业务为什么要做队列和线程池隔离",
      "应监控哪些队列饱和指标",
      "压测队列容量时要模拟哪些故障场景",
      "队列过大、过小和 FIFO 阻塞会带来什么问题",
    ],
    practiceAdvice: [
      "按最大等待时间、处理速率和突发流量估算队列容量，并用压测校准 P95/P99 延迟",
      "使用有界队列和明确拒绝策略，队列满时返回可观测的失败结果或触发降级",
      "为不同优先级和下游依赖设置独立队列或 bulkhead，并监控队列长度、等待时间、拒绝数和恢复速度",
    ],
